sparql:
SELECT DISTINCT ?song_name 
FROM <https://cograph.tech/graphs/demo-tenant/kg/spider-concert-singer>
WHERE {
    {
        SELECT (AVG(?singer_age) AS ?avg_age)
        WHERE {
            ?singer <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://cograph.tech/types/Singer> .
            ?singer <https://cograph.tech/types/Singer/attrs/age> ?singer_age .
        }
    }
    ?s <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://cograph.tech/types/Singer> .
    ?s <https://cograph.tech/types/Singer/attrs/age> ?age .
    FILTER (?age > ?avg_age)
    ?s <https://cograph.tech/onto/song_name> ?song_entity .
    ?song_entity <https://cograph.tech/types/Song/attrs/name> ?song_name .
}
